BEGIN READ ONLY;
SET LOCAL statement_timeout='15s';
SET LOCAL lock_timeout='2s';
WITH expected AS (SELECT * FROM jsonb_to_recordset('[{"identity": "public.proforma_conversion_commit_v1(uuid,uuid,uuid,uuid,jsonb,jsonb)", "digest": "4ce7c3f4dc760b229f64559a833621d7"}, {"identity": "public.proforma_conversion_preview_v1(uuid,uuid,uuid)", "digest": "05241bdeda10f0daf2bc4e2e4035bf39"}, {"identity": "public.attach_customer_to_sale(uuid,uuid,text,text,numeric)", "digest": "9120c743fca972f61b6a3f8fc36cfedf"}, {"identity": "public.create_credit_account_v2(uuid,text,text)", "digest": "7e4d3c1abe446af9720a55bc7965ba88"}, {"identity": "public.create_sale(uuid,jsonb,text,uuid)", "digest": "322c4ec027ce6f43fa73baa6e663b7ea"}, {"identity": "public.create_sale_with_payment_v4(uuid,jsonb,text,text,numeric,text,text,uuid,text,text,text,numeric,text,text,uuid)", "digest": "09c0ee2a16b55a3fcedbe85563d1b897"}, {"identity": "public.create_sale_with_payment_v6(uuid,jsonb,text,text,numeric,text,text,uuid,text,text,text,numeric,text,uuid,uuid,uuid)", "digest": "67eddab421487dc39d00da9f81f4c29e"}, {"identity": "public.get_store_sale_items(uuid)", "digest": "29616231912babcdb2e2c5ba08a33611"}, {"identity": "public.record_credit_sale_v2(uuid,uuid,numeric,text,text)", "digest": "1f3bfeed0ccb99dc0428ae77c7a7606e"}]'::jsonb) x(identity text,digest text)), checks AS (
SELECT
 (SELECT count(*) FROM expected e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.identity) WHERE p.oid IS NULL OR md5(replace(pg_get_functiondef(p.oid),E'\r','')) IS DISTINCT FROM e.digest) definition_mismatches,
 (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('proforma_conversion_preview_v1','proforma_conversion_commit_v1') AND p.prosecdef AND p.proconfig=ARRAY['search_path=pg_catalog'] AND has_function_privilege('authenticated',p.oid,'EXECUTE') AND NOT has_function_privilege('anon',p.oid,'EXECUTE') AND NOT has_function_privilege('service_role',p.oid,'EXECUTE')) safe_entrypoints,
 (SELECT c.relrowsecurity AND c.relforcerowsecurity AND NOT has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE') AND NOT has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE') FROM pg_class c WHERE c.oid='proforma_backend.sale_links'::regclass) private_rls,
 (SELECT count(*) FROM pg_constraint WHERE conrelid='proforma_backend.sale_links'::regclass AND contype IN ('p','u')) unique_keys,
 EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='proforma_backend.sale_links'::regclass AND tgname='immutable_sale_links' AND tgenabled='O') immutable_audit,
 (SELECT count(*) FROM proforma_backend.sale_links l LEFT JOIN public.sales s ON s.id=l.sale_id LEFT JOIN proforma_backend.documents d ON d.id=l.document_id WHERE s.id IS NULL OR s.organization_id<>l.organization_id OR s.store_id<>l.store_id OR d.sale_id IS DISTINCT FROM l.sale_id OR d.status<>'CONVERTED') linkage_mismatches)
SELECT jsonb_build_object('version','2026101706','readOnly',current_setting('transaction_read_only'),'status',CASE WHEN current_database()='postgres' AND definition_mismatches=0 AND safe_entrypoints=2 AND private_rls AND unique_keys=3 AND immutable_audit AND linkage_mismatches=0 THEN 'COMMITTED_SECURITY_PASS' ELSE 'FAIL_NO_CLIENT_RELEASE' END,'checks',to_jsonb(checks)) AS verification FROM checks;
ROLLBACK;
